# OpenEVV sound map: Guarani (eSpeak NG voice sai/gn), spoken by openevv's Latin American Spanish module
# with the sounds, the melody and the tones of the language itself.
# Written by engine/accent/mapwriter.py; OpenEvvFrontend reads it, and docs/LANGUAGES.md
# says what each line means. Edit freely: the file is read each time a voice starts.

template esux
style standard
vowels i e a o u
glides r R l L y w
schwa e
secondary 0

# the melody: late; a question that wants yes or no: fall
accent f0=own range=90 shape=2 accent=28 accent2=12 unstressed=-6 decl=8 declmax=30 fs=-18 fw=-12 fc=14 fe=-12 fq=-8 qreg=14 span=2 stop=0

# the words a question is asked with, which is not the question that wants yes or no
whwords any mbaʼe mbaʼépa máva mávapa moõ moõpa arakaʼe mbaʼéicha
whwords any mbaʼére mboy

# what the module says in place of a phone it is given
says C t S
says J d Z
says T s
says Y y

# the sounds of the language that the module has not, each as it differs from the phone
